@article{oai:nagoya.repo.nii.ac.jp:00026572,
author = {朴, 景淑 and PIAO, JINGSHU},
journal = {名古屋大学人文学フォーラム},
month = {Mar},
note = {Basically, different to suffix, most of the prefixes do not have the function that the parts of speech of the complex word will be changed after joining prefixes and proclitics together. However, the negative prefix "Mu" has the function that the part of speech of the complex word can be changed after joining proclitics and the prefix "Mu" together, which is different to the other suffixes. This is because the function of "Mu" is different to those of the other suffixes. However, it is not all of the complex words change the parts of speech in case of "Mu," since the part of speech of the proclitics is associated with the proclitics' meaning in case of "Mu." In this paper, the authors mainly focuses on the three Chinese characters' complex word with "Mu." According to the diachronic study on the word formation function of "Mu," and the parts of speech and meaning of the proclitics and the complex words of "Mu," the author primarily intend to demonstrate the word-formation functions and semantic functions of "Mu." The proclitics of "Mu" can be nouns, verb nouns, and the nuns which also can be adjective verbs. If the proclitic is a subjective word which indicates psychological activities, the complex word is the noun which also can be adjective verb; if the proclitic is an objective word which indicates product or concrete action, the complex word tends to be not a noun which also can be adjective verb. From diachronic viewpoint, before the middle ages, only two Chinese characters' complex word were used and the three Chinese characters' complex words with "Mu" are used from the middle ages; above all, the number of complex words with "Mu" is the largest in Meiji and Taisho Periods, and the number of complex words with "Mu" decreases in modern age.},
pages = {15--29},
title = {「無」の造語機能と意味機能 : 3字結合語を中心に},
volume = {1},
year = {2018}
}

